def transform(grid):
    # The divider separates the stacked pattern panel from the output canvas.
    # Transfer marker to the corresponding column in the right-hand 7-column panel.
    h=len(grid); w=len(grid[0]); out=[[0]*7 for _ in range(h)]
    for r,row in enumerate(grid):
        for c in range(8,w):
            if row[c]==5: out[r][c-8]=5
    return out
